function custom_csv_escape_cell($value)
{
$value=(string)$value;
$value=str_replace('"', '""', $value);
return '"' . $value . '"';
}
function custom_csv_parse_line($line)
{
$line=rtrim((string)$line, "\r\n");
if ($line==='') return array();
$cells=str_getcsv($line);
return is_array($cells) ? $cells : array();
}
